WITH attributed AS (SELECT a.*, sub.id AS subscription_id, sub.plan, sub.monthly_fee FROM sessions a JOIN subscriptions sub ON a.customer_id = sub.customer_id AND a.started_at >= sub.start_date AND a.started_at <= DATE_ADD(sub.end_date, 7)) SELECT id, customer_id, device, browser, country, subscription_id, monthly_fee, CASE WHEN country RLIKE '^(TH|DE)$' THEN 'EXTENDED' WHEN country RLIKE '^(US|SG)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS country_zone FROM attributed;
